#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("ERROR");
        return 0;
    }
    const int MAX_TOKENS = 64;
    long stack[MAX_TOKENS];
    int top = 0;
    int limit = argc - 1;
    if (limit > MAX_TOKENS) limit = MAX_TOKENS; // limit to avoid overflow
    for (int i = 1; i <= limit; ++i) {
        char *arg = argv[i];
        size_t len = strlen(arg);
        if (len == 1 && strchr("+-*/", arg[0])) {
            if (top < 2) {
                puts("ERROR");
                return 0;
            }
            long b = stack[--top];
            long a = stack[--top];
            long res = 0;
            switch (arg[0]) {
                case '+': res = a + b; break;
                case '-': res = a - b; break;
                case '*': res = a * b; break;
                case '/':
                    if (b == 0) { puts("ERROR"); return 0; }
                    res = a / b;
                    break;
            }
            stack[top++] = res;
        } else {
            char *endptr;
            long val = strtol(arg, &endptr, 10);
            if (endptr == arg) {
                puts("ERROR");
                return 0;
            }
            stack[top++] = val;
        }
    }
    if (top != 1) {
        puts("ERROR");
        return 0;
    }
    printf("%ld\n", stack[0]);
    return 0;
}
